def _build() -> dict[str, dict[str, str]]:
    out = {k: _s(*v) for k, v in _SIMPLE.items()}
    for key, (fr, en, dfr, den, lfr, len_) in _TEMPLATES.items():
        out[f"st_tpl_{key}"] = _s(fr, en)
        out[f"st_tpl_{key}_d"] = _s(dfr, den)
        out[f"st_tpl_{key}_long"] = _s(lfr, len_)
    for prefix, table in (("st_ind_", _INDICATORS), ("st_p_", _PARAMS), ("st_opt_", _OPTIONS), ("st_fam_", _FAMILIES), ("st_chk_", _CHECKS)):
        for key, (fr, en) in table.items():
            out[prefix + key] = _s(fr, en)
    return out


STRATEGIES_STRINGS: dict[str, dict[str, str]] = _build()
STRATEGIES_JS_KEYS: tuple[str, ...] = tuple(k for k in STRATEGIES_STRINGS if k.startswith("st_"))
